//! 🧪️ Original comparison laws exercise actual Source custody and separately funded native metadata.
use super::*;
use semio_framework_value_clone_source::RetainedCloneSource;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_clone_source_testing::{FixtureSourceBirth,FixtureCloseStep};
use semio_framework_value_control_contract::OriginalEffectAuthority;
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
#[path="driver.rs"]
mod driver;
use driver::{paid,grant,Driver,Context,Op,refusal};
#[test]
fn genuine_string_comparison_preserves_denials_cache_and_actual_source_bank(){
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();let stock=&law["stock"];let initial=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:stock["release"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};
 for row in law["cases"].as_array().unwrap(){
  let left=row["left"].as_str().unwrap().to_owned();let right=row["right"].as_str().unwrap().to_owned();let pointers=(left.as_ptr(),right.as_ptr());let mut left=RetainedCloneSource::from_owner_in(left,EffectBank::new(Wallet::new(initial,initial.maximum_items as u64)));let mut right=RetainedCloneSource::from_owner(right);assert_eq!(left.borrow().get().as_ptr(),pointers.0);assert_eq!(right.borrow().get().as_ptr(),pointers.1);let expected=left.borrow().get().cmp(right.borrow().get());assert_eq!(format!("{expected:?}"),row["ordering"].as_str().unwrap());
  left.with_bank(|left,bank|{let source=bank.source_witness().identity();let mut authority=OriginalEffectAuthority::new(Driver::<String>(source,std::marker::PhantomData));let(mut cursor,mut order)=(None,None);let d=String::bounded_ord_birth_demand();let g=grant(d);
   for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let mut c=Context{cursor:&mut cursor,left,right:right.borrow(),order:&mut order,source,op:Op::Birth};assert_eq!(paid(bank,&mut authority,&mut c,denied,1).progress(),Default::default());assert!(cursor.is_none())}
   let mut c=Context{cursor:&mut cursor,left,right:right.borrow(),order:&mut order,source,op:Op::Birth};let step=paid(bank,&mut authority,&mut c,g,String::bounded_ord_birth_work_demand());assert_eq!(step.progress().copied_bytes,d.copy_bytes);
   let comparison=BoundedOrdGrant{maximum_items:1,maximum_bytes:1};let mut complete=false;
   for _ in 0..law["maximumTurns"].as_u64().unwrap(){let d=cursor.as_ref().unwrap().compare_demands(left,right.borrow(),comparison,1).unwrap();let work=cursor.as_ref().unwrap().compare_work_demand(left,right.borrow(),comparison,1).unwrap();assert!(work<=law["nativePhases"]["maximumAuthenticatedWork"].as_u64().unwrap());let g=grant(d);let mut c=Context{cursor:&mut cursor,left,right:right.borrow(),order:&mut order,source,op:Op::Compare(comparison,1)};assert_eq!(paid(bank,&mut authority,&mut c,RetainedCloneGrant{maximum_items:0,..g},work).progress(),Default::default());let step=paid(bank,&mut authority,&mut c,g,work);assert_eq!(step.progress().retained_capacity_bytes,0);if let Some(ordering)=cursor.as_ref().unwrap().ordering(){assert_eq!(ordering,expected);complete=true;break}}
   assert!(complete);let mut c=Context{cursor:&mut cursor,left,right:right.borrow(),order:&mut order,source,op:Op::Compare(BoundedOrdGrant::default(),1)};assert_eq!(paid(bank,&mut authority,&mut c,RetainedCloneGrant::default(),law["cachedWork"].as_u64().unwrap()).progress(),Default::default());assert_eq!(cursor.as_ref().unwrap().ordering(),Some(expected));let mut replacement=RetainedCloneSource::from_owner(row["left"].as_str().unwrap().to_owned());let mut c=Context{cursor:&mut cursor,left:replacement.borrow(),right:right.borrow(),order:&mut order,source,op:Op::Compare(BoundedOrdGrant::default(),1)};refusal(bank,&mut authority,&mut c,RetainedCloneGrant::default(),law["nativePhases"]["foreignSourceWork"].as_u64().unwrap(),"projected path changed");for _ in 0..law["maximumTurns"].as_u64().unwrap(){if replacement.terminal_is_empty(){break}let _=replacement.close_once().unwrap();}assert!(replacement.terminal_is_empty());
   let d=cursor.as_ref().unwrap().take_ordering_demand();let mut c=Context{cursor:&mut cursor,left,right:right.borrow(),order:&mut order,source,op:Op::Take};paid(bank,&mut authority,&mut c,grant(d),1);assert_eq!(order,Some(expected));let d=cursor.as_ref().unwrap().begin_close_demand();let mut c=Context{cursor:&mut cursor,left,right:right.borrow(),order:&mut order,source,op:Op::BeginClose};paid(bank,&mut authority,&mut c,grant(d),1);
   for _ in 0..law["maximumTurns"].as_u64().unwrap(){if cursor.as_ref().unwrap().terminal_is_empty(){break}let d=cursor.as_ref().unwrap().close_demands(1).unwrap();let work=cursor.as_ref().unwrap().close_work_demand(1).unwrap();let mut c=Context{cursor:&mut cursor,left,right:right.borrow(),order:&mut order,source,op:Op::Close(1)};paid(bank,&mut authority,&mut c,grant(d),work);}
   assert!(cursor.as_ref().unwrap().terminal_is_empty());let d=cursor.as_ref().unwrap().terminal_release().unwrap().inline_demand();let mut c=Context{cursor:&mut cursor,left,right:right.borrow(),order:&mut order,source,op:Op::Release};paid(bank,&mut authority,&mut c,grant(d),1);assert!(cursor.is_none());assert!(authority.into_producer().is_ok());
  }).unwrap();
  for source in [&mut left,&mut right]{for _ in 0..law["maximumTurns"].as_u64().unwrap(){if source.terminal_is_empty(){break}assert!(!matches!(source.close_once().unwrap(),FixtureCloseStep::Denied|FixtureCloseStep::Blocked))}assert!(source.terminal_is_empty())}
 }
}
#[test]
fn native_comparator_admission_keeps_denials_and_actual_receipt_in_resident_slots(){
 use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};use semio_framework_value_control_contract::{OriginalEffectReply,RetainedWorkOutcome,RetainedWorkPoll};let mut bank=EffectBank::new(Wallet::new(RetainedCloneGrant{maximum_items:64,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:32},128));let d=String::bounded_ord_birth_demand();let g=grant(d);let mut output=None;for (request,work,admitted)in [(g,0,false),(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},1,false),(g,1,true)]{let mut answer=None;let((poll,marker),heap)=observe(||bank.run(request,work,|effect|{let before=effect.performed_boundary();drop(String::admit_bounded_ord_cursor_into(&mut output,effect,OriginalEffectReply::borrow(&mut answer).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:effect.performed_since(before).unwrap()})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native admission stayed pending")};turn.result.unwrap();assert_eq!(turn.work,u128::from(admitted));assert_eq!(marker,None);assert_eq!(heap,(0,0));let step=answer.take().unwrap().unwrap();assert_eq!(step.progress().copied_bytes,if admitted{d.copy_bytes}else{0});assert_eq!(output.is_some(),admitted);assert_eq!(bank.take_admitted(),admitted.then_some(true));bank.post(step.progress(),request,heap)}let cursor=output.as_ref().unwrap();assert!(cursor.terminal_is_empty());let release=cursor.terminal_release().expect("actual empty native cursor lifecycle");let d=release.inline_demand();let request=grant(d);let mut answer=None;let((poll,marker),heap)=observe(||bank.run(request,1,|effect|{let before=effect.performed_boundary();drop(release.inline_into(&mut output,effect,OriginalEffectReply::borrow(&mut answer).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:effect.performed_since(before).unwrap()})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native cursor release stayed pending")};turn.result.unwrap();assert_eq!(marker,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(answer.take().unwrap().unwrap().progress(),request,heap);assert!(output.is_none());
}


#[test]
fn logical_comparison_totals_survive_denial_cached_reply_and_paid_close(){let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();for row in law["logicalCounters"].as_array().unwrap(){let mut left=RetainedCloneSource::from_owner(row["left"].as_str().unwrap().to_owned());let mut right=RetainedCloneSource::from_owner(row["right"].as_str().unwrap().to_owned());left.with_bank(|left,bank|{let source=bank.source_witness().identity();let mut authority=OriginalEffectAuthority::new(Driver::<String>(source,std::marker::PhantomData));let(mut cursor,mut order)=(None,None);let mut c=Context{cursor:&mut cursor,left,right:right.borrow(),order:&mut order,source,op:Op::Birth};paid(bank,&mut authority,&mut c,grant(String::bounded_ord_birth_demand()),1);let comparison=BoundedOrdGrant{maximum_items:1,maximum_bytes:2};for _ in 0..100{if cursor.as_ref().unwrap().ordering().is_some(){break}let before=cursor.as_ref().unwrap().comparison_totals();let d=cursor.as_ref().unwrap().compare_demands(left,right.borrow(),comparison,2).unwrap();let work=cursor.as_ref().unwrap().compare_work_demand(left,right.borrow(),comparison,2).unwrap();let mut c=Context{cursor:&mut cursor,left,right:right.borrow(),order:&mut order,source,op:Op::Compare(comparison,2)};paid(bank,&mut authority,&mut c,RetainedCloneGrant{maximum_items:0,..grant(d)},work);assert_eq!(cursor.as_ref().unwrap().comparison_totals(),before);let mut c=Context{cursor:&mut cursor,left,right:right.borrow(),order:&mut order,source,op:Op::Compare(comparison,2)};paid(bank,&mut authority,&mut c,grant(d),work);}let total=cursor.as_ref().unwrap().comparison_totals();assert_eq!(total,BoundedOrdProgress{compared_items:row["comparedItems"].as_u64().unwrap()as usize,compared_bytes:row["comparedBytes"].as_u64().unwrap()as usize});let mut c=Context{cursor:&mut cursor,left,right:right.borrow(),order:&mut order,source,op:Op::Compare(BoundedOrdGrant::default(),2)};paid(bank,&mut authority,&mut c,RetainedCloneGrant::default(),0);assert_eq!(cursor.as_ref().unwrap().comparison_totals(),total);driver::close_comparator(&mut cursor,left,right.borrow(),bank,&mut authority,2);assert!(authority.into_producer().is_ok());}).unwrap();for input in [&mut left,&mut right]{for _ in 0..10000{if input.terminal_is_empty(){break}input.close_once().unwrap();}assert!(input.terminal_is_empty())}}}
